namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ProcessedReturns _processedReturns;
    private readonly RestockLedger _restockLedger;
    private readonly ReturnAcceptance _returnAcceptance;
    private readonly RefundProcessor _refundProcessor;

    public ReturnsHandler()
    {
        _processedReturns = new ProcessedReturns();
        _restockLedger = new RestockLedger();
        _returnAcceptance = new ReturnAcceptance(_processedReturns, _restockLedger);
        _refundProcessor = new RefundProcessor();
    }

    public string ProcessReturn(Order order, Customer customer)
    {
        return _returnAcceptance.Process(order, customer);
    }

    public bool IsReturnable(Order order)
    {
        return _returnAcceptance.IsReturnable(order);
    }

    public decimal ComputeRefund(Order order)
    {
        return _refundProcessor.Compute(order);
    }

    public void LogRefund(Order order, decimal amount)
    {
        _refundProcessor.Log(order, amount);
    }

    public int Restock(Order order)
    {
        return _restockLedger.Restock(order);
    }

    private sealed class ReturnAcceptance
    {
        private readonly ProcessedReturns _processedReturns;
        private readonly RestockLedger _restockLedger;

        public ReturnAcceptance(ProcessedReturns processedReturns, RestockLedger restockLedger)
        {
            _processedReturns = processedReturns;
            _restockLedger = restockLedger;
        }

        public string Process(Order order, Customer customer)
        {
            if (string.IsNullOrEmpty(order.Reference))
                return "missing reference";
            if (_processedReturns.Contains(order.Reference))
                return "already processed";
            if (order.Lines.Count == 0)
                return "nothing to return";
            if (customer.Tier == CustomerTier.Blocked)
                return "customer blocked";

            var error = _restockLedger.RecordReturnedLines(order);
            if (error is not null)
                return error;
            if (!_restockLedger.HasEntries)
                return "no returnable lines";

            _processedReturns.Add(order.Reference);
            return "accepted";
        }

        public bool IsReturnable(Order order)
        {
            if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
                return false;
            if (_processedReturns.Contains(order.Reference))
                return false;

            int valid = 0;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (string.IsNullOrEmpty(line.Sku))
                    continue;
                if (line.Quantity > 100)
                    continue;
                if (line.Quantity >= 1 && line.Quantity <= 100)
                    valid++;
            }

            return valid > 0;
        }
    }

    private sealed class ProcessedReturns
    {
        private readonly HashSet<string> _references = new(StringComparer.Ordinal);

        public bool Contains(string reference)
        {
            return _references.Contains(reference);
        }

        public void Add(string reference)
        {
            _references.Add(reference);
        }
    }

    private sealed class RestockLedger
    {
        private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

        public bool HasEntries => _restockBySku.Count != 0;

        public string? RecordReturnedLines(Order order)
        {
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (line.Quantity > 100)
                    return "quantity too high";

                _restockBySku[line.Sku] = _restockBySku.TryGetValue(line.Sku, out var count)
                    ? count + line.Quantity
                    : line.Quantity;
            }

            return null;
        }

        public int Restock(Order order)
        {
            int moved = 0;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;

                var sku = line.Sku;
                if (string.IsNullOrEmpty(sku))
                    continue;
                if (line.Quantity > 100)
                    continue;

                if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
                {
                    moved += pending;
                    _restockBySku[sku] = 0;
                }
                else if (line.Quantity > 50)
                {
                    _restockBySku[sku] = line.Quantity / 2;
                }
                else if (line.Quantity > 0)
                {
                    _restockBySku[sku] = line.Quantity;
                }

                if (moved > 100000)
                    break;
            }

            return moved;
        }
    }

    private sealed class RefundProcessor
    {
        private const decimal UnitRefund = 5m;
        private readonly List<string> _refundLog = new();

        public decimal Compute(Order order)
        {
            decimal refund = 0m;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (line.Quantity > 50)
                    refund += line.Quantity * UnitRefund * 0.9m;
                else if (line.Quantity > 10)
                    refund += line.Quantity * UnitRefund * 0.95m;
                else if (line.Quantity > 1)
                    refund += line.Quantity * UnitRefund;
                else
                    refund += UnitRefund;
            }

            if (_refundLog.Count > 1000 && refund > 0m)
                refund = Math.Min(refund, 10000m);
            if (refund > 5000m)
                refund *= 0.99m;
            return refund < 0m ? 0m : refund;
        }

        public void Log(Order order, decimal amount)
        {
            if (amount <= 0m)
                return;
            if (string.IsNullOrEmpty(order.Reference))
                return;

            if (_refundLog.Count == 0 || amount > 100m)
                _refundLog.Add($"{order.Reference}:{amount}");
            else if (amount > 50m)
                _refundLog.Add($"{order.Reference}:large:{amount}");
            else if (amount > 10m)
                _refundLog.Add($"{order.Reference}:mid:{amount}");
            else
                _refundLog.Add($"{order.Reference}:small:{amount}");

            if (_refundLog.Count > 500 && amount > 1000m)
                _refundLog.Add($"{order.Reference}:flag");
        }
    }
}
